    /// 删 bin/；--purge 才删整个管理根。
    Uninstall {
        #[arg(long)]
        purge: bool,
        /// --purge 时跳过确认。
        #[arg(long)]
        yes: bool,
    },
    /// 版本、平台、管理根、SCHEMA_VERSION。
    Version,
}

#[derive(Debug, Subcommand)]
pub enum WorkbookCmd {
    /// 校验并复制一个 Workbook 目录到管理根。
    Add { dir: String },
    /// 列出已装 Workbook。
    List,
    /// 打印 manifest、宿主资源声明与每个 Flow 的节点、边。
